<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/UserAccessFixture.php';
// YII2-USER-ACCESS-001: real clicks/forms + independent persisted-facts observation.
$f=null;$process=null;$configPath=null;
try{
$f=new UserAccessFixture(dirname(__DIR__,2));$f->start();$configPath=$f->artifacts.'/browser.json';file_put_contents($configPath,json_encode(['origin'=>'http://127.0.0.1:'.$f->server['port'],'email'=>$f->auth->email,'password'=>$f->auth->password,'artifacts'=>$f->artifacts,'result'=>$f->artifacts.'/result.json','playwright'=>getenv('FMONITOR_TEST_PLAYWRIGHT_MODULE')?:dirname($f->root).'/shlz-ui/node_modules/playwright'],JSON_THROW_ON_ERROR));chmod($configPath,0600);
$process=proc_open([getenv('FMONITOR_TEST_NODE_BINARY')?:'node',__DIR__.'/user_access_browser.mjs',$configPath],[0=>['file','/dev/null','r'],1=>['file',$f->artifacts.'/browser.log','a'],2=>['file',$f->artifacts.'/browser.log','a']],$pipes,$f->root);if(!is_resource($process))throw new TestFailure('SETUP_FAILURE: browser process');$deadline=microtime(true)+90;
do{$state=proc_get_status($process);if(!$state['running'])break;usleep(20000);}while(microtime(true)<$deadline);if($state['running'])throw new TestFailure('browser deadline; '.$f->artifacts);$exit=$state['exitcode'];proc_close($process);$process=null;assertSameValue(0,$exit,'browser flow; '.file_get_contents($f->artifacts.'/browser.log'));
