$history=$f->db->query("SELECT * FROM {$f->p}fm2_pilot_invitations WHERE user_id=$id ORDER BY id")->fetch_all(MYSQLI_ASSOC);assertSameValue(2,count($history),'one issue + one reissue');assertSameValue(true,$history[0]['revoked_at']!==null&&$history[1]['used_at']!==null,'old revoked new used');
$roles=$f->db->query("SELECT role_id FROM {$f->p}fm2_pilot_user_roles WHERE user_id=$id ORDER BY role_id")->fetch_all(MYSQLI_ASSOC);assertSameValue([9210,9212],array_map('intval',array_column($roles,'role_id')),'exact role assignments');$events=$f->db->query("SELECT action,actor_user_id FROM {$f->p}fm2_pilot_user_role_events WHERE user_id=$id ORDER BY id")->fetch_all(MYSQLI_ASSOC);assertSameValue(['role_attached'],array_column($events,'action'),'one browser role event');assertSameValue([9101],array_map('intval',array_column($events,'actor_user_id')),'browser role actor');$status=$f->db->query("SELECT action,actor_user_id FROM {$f->p}fm2_pilot_user_status_events WHERE user_id=$id ORDER BY id")->fetch_all(MYSQLI_ASSOC);assertSameValue(['user_blocked','user_unblocked'],array_column($status,'action'),'browser status history');assertSameValue([9101,9101],array_map('intval',array_column($status,'actor_user_id')),'status actors');
$f->noLegacy();echo 'PASS: YII2-USER-ACCESS-001 real browser and independent facts; artifacts '.$f->artifacts."\n";
